def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = 0
    my_d_total = 0
    dc_count = 0
    punished = 0

    for i in range(n):
        m = me[i]
        o = opp[i]
        if o == 'C':
            opp_c += 1
        if m == 'D':
            my_d_total += 1
        if m == 'D' and o == 'C':
            dc_count += 1
        if i > 0 and me[i - 1] == 'D' and opp[i] == 'D':
            punished += 1

    opp_d = n - opp_c

    opp_d_streak = 0
    for x in reversed(opp):
        if x == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for x in reversed(opp):
        if x == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for x in reversed(me):
        if x == 'D':
            my_d_streak += 1
        else:
            break

    unprov = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if me[i] == 'C' and opp[i] == 'D':
            unprov += 1

    if last_opp == 'C':
        if last_me == 'D':
            if punished == 0 and dc_count >= 2 and opp_c_streak >= 2:
                return 'D'
            if punished == 0 and dc_count >= 5 and my_d_streak >= 2:
                return 'D'
            return 'C'

        if n == 15 and opp_c == n and my_d_total == 0:
            return 'D'

        if punished == 0 and n >= 2:
            if me[-2] == 'D' and opp[-2] == 'C':
                return 'D'

        return 'C'

    if last_me == 'D':
        if opp_d_streak >= 15 and opp_c_streak == 0 and n > 20:
            return 'D'
        if my_d_streak >= 6:
            return 'C'
        return 'D'

    if n >= 2 and me[-2] == 'D':
        attempts = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'C' and opp[i] == 'D':
                attempts += 1
            else:
                break
        if attempts <= 1 and not (opp_d_streak >= 15 and opp_c_streak == 0 and n > 20):
            return 'C'
        return 'D'

    if opp_d_streak == 1 and opp_c * 5 >= n * 3 and unprov <= 3:
        return 'C'

    if opp_d_streak == 2 and opp_c * 5 >= n * 4 and unprov <= 2:
        return 'C'

    return 'D'
